CREATE OR REPLACE FUNCTION ECAMS.CHECKINYN
(SCMUSER IN VARCHAR2,ISRID IN VARCHAR2,REQCD IN VARCHAR2,USERID IN VARCHAR2,STATUS IN VARCHAR2)
RETURN VARCHAR2
IS
   VCNT  INT := 0;

--변경관리 권한 체크
BEGIN
    IF REQCD = '41' THEN    --SR등록
       IF STATUS<>'0' AND STATUS<>'1' AND STATUS<>'2' AND STATUS<>'A' AND STATUS<>'C' THEN
          RETURN 'NO';
       END IF;
       
       SELECT COUNT(*)
         INTO VCNT
         FROM CMR0020 A
        WHERE A.CR_ISRID=ISRID
          AND NVL(A.CR_CKOUTUSER,A.CR_EDITOR)=SCMUSER
          AND A.CR_STATUS<>'0';
       IF VCNT > 0 THEN
          RETURN 'NO4101';
       ELSE
          RETURN 'OK';
       END IF;
