    ELSIF REQCD = '07' OR REQCD = '11' THEN
       SELECT COUNT(*)
         INTO VCNT
         FROM CMR0020
        WHERE CR_ISRID=ISRID
          AND NVL(CR_CKOUTUSER,CR_EDITOR)=SCMUSER
          AND CR_STATUS IN ('3','5','B','E','G');
       IF VCNT > 0 THEN
          RETURN 'OK';
       ELSE
          RETURN 'NO00';
       END IF;
    ELSIF REQCD = '08' THEN
       -- 개발서버존재여부 CHECK
       SELECT COUNT(*)
         INTO VCNT
         FROM CMR0020 A
        WHERE CR_ISRID=ISRID
          AND NVL(CR_CKOUTUSER,CR_EDITOR)=SCMUSER
          AND TESTSVR_YN(A.CR_SYSCD,REQCD)='OK';
       IF VCNT = 0 THEN
          RETURN 'NO00';
       END IF;

       --테스트서버가 존재하지 않으면 체크인완료 또는 개발적용완료
       SELECT COUNT(*)
         INTO VCNT
         FROM CMR0020 A
        WHERE CR_ISRID=ISRID
          AND NVL(CR_CKOUTUSER,CR_EDITOR)=SCMUSER
          AND TESTSVR_YN(A.CR_SYSCD,'03')<>'OK'
          AND CR_STATUS IN ('B','E');
       IF VCNT > 0 THEN
          RETURN 'OK';
       END IF;

       --테스트서버가 존재하면 체크인완료,개발적용완료,테스트적용완료
       SELECT COUNT(*)
         INTO VCNT
         FROM CMR0020 A
        WHERE CR_ISRID=ISRID
          AND NVL(CR_CKOUTUSER,CR_EDITOR)=SCMUSER
          AND TESTSVR_YN(A.CR_SYSCD,'03')='OK'
          AND CR_STATUS IN ('B','E','G');
       IF VCNT > 0 THEN
          RETURN 'OK';
       END IF;

       RETURN 'NO01';

    ELSIF REQCD = '03' THEN
       -- 테스트서버존재여부 CHECK
       SELECT COUNT(*)
         INTO VCNT
         FROM CMR0020 A
        WHERE CR_ISRID=ISRID
          AND NVL(CR_CKOUTUSER,CR_EDITOR)=SCMUSER
          AND TESTSVR_YN(A.CR_SYSCD,REQCD)='OK';
       IF VCNT = 0 THEN
          RETURN 'NO00';
       ELSE RETURN 'OK';
       END IF;

       -- 개발서버존재하면 개발적용완료 또는 테스트적용완료인 경우
       SELECT COUNT(*)
         INTO VCNT
         FROM CMR0020 A
        WHERE CR_ISRID=ISRID
          AND NVL(CR_CKOUTUSER,CR_EDITOR)=SCMUSER
          AND TESTSVR_YN(A.CR_SYSCD,'08')='OK'
          AND CR_STATUS IN ('E','G');
       IF VCNT > 0 THEN
          RETURN 'OK';
       END IF;

       -- 개발서버미존재하면 체크인완료 또는 테스트적용완료인 경우
       SELECT COUNT(*)
         INTO VCNT
         FROM CMR0020 A
        WHERE CR_ISRID=ISRID
          AND NVL(CR_CKOUTUSER,CR_EDITOR)=SCMUSER
