          AND CR_STATUS IN ('B','G');
       IF VCNT > 0 THEN
          RETURN 'OK';
       END IF;

       RETURN 'NO01';

    ELSIF REQCD = '04' THEN
       --프로그램이 존재하는지 조회
       SELECT COUNT(*)
