         FROM CMR0020
        WHERE CR_ISRID = ISRID
          AND NVL(CR_CKOUTUSER,CR_EDITOR)=SCMUSER
          AND CR_STATUS not in ('0','9');
          
       IF VCNT > 0 THEN
            --테스트요청이 존재하는지 조회
           SELECT COUNT(*)
             INTO VCNT
             FROM CMR0020 A
            WHERE CR_ISRID=ISRID
              AND NVL(CR_CKOUTUSER,CR_EDITOR)=SCMUSER
