                FROM CMR0020
               WHERE CR_ISRID=ISRID
                 AND NVL(CR_CKOUTUSER,CR_EDITOR)=SCMUSER
                 --AND CR_STATUS not in ('G','0','9');
                 AND CR_STATUS in ('3','5','B');
           ELSE
