                 INTO VCNT
                 FROM CMR0020
                WHERE CR_ISRID=ISRID
                  AND NVL(CR_CKOUTUSER,CR_EDITOR)=SCMUSER
                  --AND CR_STATUS not in ('B','0','9');
                  AND CR_STATUS in ('3','5');
           END IF;
           
           IF VCNT > 0 THEN
              RETURN 'OK';
           ELSE
              RETURN 'NOST';
           END IF;
       ELSE
          RETURN 'NO';
       END IF;
       
       

    ELSIF REQCD = '69' THEN    --SR중단
