         FROM CMR0020 A
        WHERE A.CR_ISRID=ISRID
          AND NVL(CR_CKOUTUSER,CR_EDITOR)=SCMUSER
          AND A.CR_STATUS<>'0';
       IF VCNT > 0 THEN
          RETURN 'NO4101';
       ELSE
          RETURN 'OK';
       END IF;
